/* Modelo de deck independente da interface. Contagens usam ID, nunca a arte. */
(() => {
  const rules={checkedAt:'2026-10-23',effectiveAt:'2026-10-12',source:'https://en.onepiece-cardgame.com/news/restriction.html',banned:['OP06-047','OP03-040','OP06-086','ST10-001','OP06-116','OP14-020'],pairs:[['OP07-115','EB04-058'],['OP11-040','OP11-067'],['OP11-040','OP08-069']]};
  const total=deck=>Object.values(deck.cards||{}).reduce((n,row)=>n+row.qty,0);
  const colors=card=>(card?.color||'').split('/').filter(Boolean);
  const compatible=(leader,card)=>!!leader&&['CHARACTER','EVENT','STAGE'].includes(card.type)&&colors(card).every(color=>colors(leader).includes(color));
  const limit=card=>/may (?:have|include) any number|can (?:have|include) any number/i.test(card.effect||'')?50:4;
  const preview=card=>!!card.spoiler||(card.releaseDate&&card.releaseDate>'2026-10-23');
  function validate(deck,lookup){const errors=[],notes=[];const leader=lookup.get(deck.leader);const count=total(deck);if(!leader||leader.type!=='LEADER')errors.push('Escolha um Líder.');if(count!==50)errors.push(`O deck principal precisa de 50 cartas; agora tem ${count}.`);if(deck.donCount!==10)errors.push('O deck de DON!! precisa de 10 cartas.');
    const present=new Set(leader?[leader.id]:[]);for(const[id,row]of Object.entries(deck.cards||{})){const card=lookup.get(row.uid)||lookup.get(id);if(!card){errors.push('ID desconhecido: '+id);continue;}present.add(card.id);if(!Number.isInteger(row.qty)||row.qty<1||row.qty>50)errors.push('Quantidade inválida em '+id);if(!compatible(leader,card))errors.push(`${id} não é compatível com as cores do Líder ou não pertence ao deck principal.`);if(row.qty>limit(card))errors.push(`${id} excede o limite de ${limit(card)} cópias por ID.`);if(preview(card))notes.push(`${id} é prévia ou tem lançamento futuro no registro.`);}
    if(leader&&preview(leader))notes.push(`${leader.id} é um Líder em prévia.`);
    const restricted=rules.banned.filter(id=>present.has(id));const pairs=rules.pairs.filter(pair=>pair.every(id=>present.has(id)));
    restricted.forEach(id=>notes.push(id+' está na lista de banidas consultada.'));pairs.forEach(pair=>notes.push('Par proibido na lista consultada: '+pair.join(' + ')));
    if(deck.format==='standard'){
      if(restricted.length)errors.push('Há cartas banidas na lista consultada.');if(pairs.length)errors.push('Há um par proibido na lista consultada.');if([...present].some(id=>preview(lookup.get(id)||{})))errors.push('Prévias não entram na revisão Standard.');
      for(const id of present){const c=lookup.get(id);if(!c)continue;const blocks=c.legalBlocks?.length?c.legalBlocks:[c.block];if(!blocks.some(b=>['2','3','4','5','X'].includes(String(b))))notes.push(`${id}: conferir a elegibilidade de bloco e eventuais atualizações por ID.`);}
    }
    return{errors:[...new Set(errors)],notes:[...new Set(notes)],count,ready:errors.length===0};
  }
  function add(deck,card,lookup){const leader=lookup.get(deck.leader);if(!leader)return'Escolha um Líder primeiro.';if(!compatible(leader,card))return'As cores desta carta não são compatíveis com o Líder.';if(total(deck)>=50)return'O deck principal já tem 50 cartas.';const existing=deck.cards[card.id];if((existing?.qty||0)>=limit(card))return`Limite de ${limit(card)} cópias para ${card.id}, contando todas as artes.`;deck.cards[card.id]={uid:existing?.uid||card.uid,qty:(existing?.qty||0)+1};return null;}
  function parseImport(raw,lookup){const data=typeof raw==='string'?JSON.parse(raw):raw;if(!data||data.schema!=='grand-line-atlas-deck-v1'||typeof data.name!=='string'||!Array.isArray(data.cards)||data.cards.length>100)throw Error('Arquivo de deck inválido. Use uma exportação JSON do Atlas.');const leader=lookup.get(data.leader);if(!leader||leader.type!=='LEADER')throw Error('Líder não encontrado.');const deck={name:data.name.slice(0,80),leader:leader.uid,format:data.format==='standard'?'standard':'study',donCount:10,donArt:null,cards:{}};if(data.donArt){const don=lookup.get(data.donArt);if(!don||don.type!=='DON')throw Error('Arte de DON!! inválida.');deck.donArt=don.uid;}for(const row of data.cards){const card=lookup.get(row.uid)||lookup.get(row.id);if(!card||!['CHARACTER','EVENT','STAGE'].includes(card.type)||!Number.isInteger(row.quantity)||row.quantity<1||row.quantity>50)throw Error('Carta ou quantidade inválida no arquivo.');deck.cards[card.id]={uid:card.uid,qty:(deck.cards[card.id]?.qty||0)+row.quantity};}if(total(deck)>50)throw Error('O arquivo excede 50 cartas no deck principal.');return deck;}
  function exported(deck){return{schema:'grand-line-atlas-deck-v1',name:deck.name,leader:deck.leader,format:deck.format,donArt:deck.donArt||null,donCount:10,cards:Object.entries(deck.cards).map(([id,row])=>({id,uid:row.uid,quantity:row.qty}))};}
  function analyze(deck,lookup){const curve=[0,0,0,0,0,0,0],types={CHARACTER:0,EVENT:0,STAGE:0};let counters=0;for(const row of Object.values(deck.cards)){const c=lookup.get(row.uid);if(!c)continue;types[c.type]+=row.qty;const cost=/^\d+$/.test(c.cost)?+c.cost:null;if(cost!==null)curve[Math.min(6,cost)]+=row.qty;if(/^\d+$/.test(c.counter)&&+c.counter>0)counters+=row.qty;}return{curve,types,counters};}
  window.AtlasDeck={rules,total,compatible,limit,preview,validate,add,parseImport,exported,analyze};
})();
